namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        Add("Welcome to the notification center!");
        Add("Your profile was updated successfully.");
        Add("New comment on your post.");
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    public List<Notification> GetSince(int lastId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called by a hosted service to keep the fake data flowing.
    /// </summary>
    public void GenerateRandom()
    {
        string[] templates =
        [
            "Server CPU usage is at {0}%",
            "User {0} just signed up",
            "Deployment #{0} completed",
            "Disk usage warning: {0}% full",
            "New order #{0} received",
        ];

        var template = templates[Random.Shared.Next(templates.Length)];
        var value = Random.Shared.Next(1, 100);
        Add(string.Format(template, value));
    }

    private void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }
}

namespace BlazorNotifications.Services;

/// <summary>
/// Background service that periodically generates fake notifications
/// so the polling page has new data to discover.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.GenerateRandom();
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    // Runs during prerender AND when the circuit starts.
    // We load data here so the initial SSR HTML already contains notifications.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _lastSeenId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;
    }

    // Only fires once after the component is truly interactive (not during prerender).
    // This is where we start the polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newer = NotificationSvc.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

